 template<class T>static const T*reloadVoiceTask(const StateReloadVoiceService&s){using C=StateReloadVoiceService::Component;if constexpr(std::is_same_v<T,StateReloadVoiceService>)return &s;else if constexpr(std::is_same_v<T,VoiceReleaseTask>)return s.component()==C::Voices?s.voiceTask():nullptr;else if constexpr(std::is_same_v<T,PartSignalTask>)return s.component()==C::Signal?s.signalTask():nullptr;else if constexpr(std::is_same_v<T,PartLookupTask>)return s.component()==C::Lookup?s.lookupTask():nullptr;else if constexpr(std::is_same_v<T,DspRoutingTask>)return s.component()==C::Route?s.routingTask():nullptr;else if constexpr(std::is_same_v<T,DspSelectTask>)return s.component()==C::Select?s.selectTask():nullptr;else if constexpr(std::is_same_v<T,DspAddressTask>)return s.component()==C::Address?s.addressTask():nullptr;else if constexpr(std::is_same_v<T,DspWordTask>)return s.component()==C::Word?s.wordTask():nullptr;else if constexpr(std::is_same_v<T,VoiceGateOffTask>)return s.component()==C::Gate?s.gateTask():nullptr;else if constexpr(std::is_same_v<T,KeyResetTask>)return s.component()==C::Keys?s.keyTask():nullptr;else if constexpr(std::is_same_v<T,DspFaultTask>)return s.component()==C::Fault?s.faultTask():nullptr;else return nullptr;}
